// coverage sketch for: Virtual Singapore
const sats = 7, beam = 30, pts = 72; let covered = 0;
for (let p = 0; p < pts; p++) {
  const lon = p * 5; let ok = false;
  for (let k = 0; k < sats; k++) {
    const d = Math.abs(((lon - k * (360 / sats) + 540) % 360) - 180);
    if (d < beam) ok = true;
  }
  if (ok) covered++;
}
console.log(JSON.stringify({ satellites: sats, beamDeg: beam, points: pts, covered: covered,
  coveragePct: +(100 * covered / pts).toFixed(1) }));

